
import React, { useState } from "react";

import "./styles.css"
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { ObjectKeys, gen16CodeId, getStore, hasWritePrivilege } from "../../../stores/Utils";
import { LocationItem_Cmpt } from "..";
import AddAreaLocation from "./AddAreaLocation";
import { SvgIcon_Cmpt } from "../../../components";
