import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId,  fetchEncryptStream, qryStore } from "../../../stores/Utils";

import { CheckBoxSlide_Cmpt, TextInput_Cmpt, CheckBox_Cmpt, DropDwnPicker_Cmpt } from "../../../components";


import "./dashboard.css"
import { CloseModal } from "../../../components/DialogHRM";

const CheckBoxSlide = CheckBoxSlide_Cmpt();
const TextInput = TextInput_Cmpt();

const CheckBox = CheckBox_Cmpt();

const DropDwnPicker = DropDwnPicker_Cmpt();


const frmNm = "new_area_location"

const AddAreaLocation  = ({ data, confirm }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};


	const save  = async ()  => {
		let ffm = getStore(frmNm);
		ffm["areaLocationId"] = gen16CodeId();

		
		
		let bdyq2 = {...getStore(qryStore())?.add_area_location};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId
		}
		bdyq2.form=ffm;


		
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			updStore(frmNm, {});
			confirm && confirm();
			data?.modalID && CloseModal({id:data?.modalID})
		}
		
	};





	const clean = (f) => {
		updStore(frmNm, {});
		set_obs(gen16CodeId())
	};

	


	return (
		<div style={{
			maxHeight: "80vh",
			width: "560px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
				Add Location
				</p>
				<div className="flexSpace"/>
				
			</div>

			
			
			<div className="_dsplFlx spaceAround" >
					<DropDwnPicker 
						init={getStore(frmNm)?.["areaId"]}
						lbl_empty={"Area"} 
						list={[
							{label:"Almacen", id:"WH"},
							{label:"Production", id:"PR"},
							{label:"Patio", id:"PT"},
						]} 
						onSelect={(e)=>updFrm("areaId",e.id)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"220px"}
					/>
				</div>
				<div className="_dsplFlx spaceAround" style={{marginTop:20}}>
					<TextInput  
						init={getStore(frmNm)?.["location"]} 
						label={"Location"} 
						width={320} 
						updChanges={(e)=>updFrm("location",e)}
					/>
				</div>

			
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				<div className="card">
					<button onClick={save}>
						Guardar
					</button>
				</div>

			</div>
		

			
		</div>
	);
};

export default AddAreaLocation;